   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "participant_email",
   "type": "string",
   "required": false,
   "description": "Email of the payer or debtors to filter expenses.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "min_amount",
   "type": "number",
   "required": false,
   "description": "Filter expenses by minimum amount.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "max_amount",
   "type": "number",
